export type RateLimiterMode = 'fixed' | 'sliding'

export interface RateLimiterOptions {
  max: number
  windowMs: number
  mode: RateLimiterMode
}

interface FixedEntry {
  windowStart: number
  count: number
}

export class RateLimiter {
  private readonly max: number
  private readonly windowMs: number
  private readonly mode: RateLimiterMode
  private readonly fixedEntries = new Map<string, FixedEntry>()
  private readonly slidingTimestamps = new Map<string, number[]>()

  constructor(options: RateLimiterOptions) {
    this.max = options.max
    this.windowMs = options.windowMs
    this.mode = options.mode
  }

  allow(key: string): boolean {
    const now = Date.now()
    if (this.mode === 'fixed') {
      return this.allowFixed(key, now)
    }
    return this.allowSliding(key, now)
  }

  private allowFixed(key: string, now: number): boolean {
    const windowStart = Math.floor(now / this.windowMs) * this.windowMs
    const entry = this.fixedEntries.get(key)
    if (!entry || entry.windowStart !== windowStart) {
      this.fixedEntries.set(key, { windowStart, count: 1 })
      return true
    }
    if (entry.count >= this.max) return false
    entry.count += 1
    return true
  }

  private allowSliding(key: string, now: number): boolean {
    const cutoff = now - this.windowMs
    const timestamps = this.slidingTimestamps.get(key) ?? []
    let firstFresh = 0
    while (firstFresh < timestamps.length && timestamps[firstFresh] <= cutoff) {
      firstFresh += 1
    }
    const fresh = firstFresh > 0 ? timestamps.slice(firstFresh) : timestamps
    if (fresh.length >= this.max) {
      this.slidingTimestamps.set(key, fresh)
      return false
    }
    fresh.push(now)
    this.slidingTimestamps.set(key, fresh)
    return true
  }
}

import { describe, it, expect, beforeEach, vi, afterEach } from 'vitest'
import { RateLimiter } from '../src/rate-limiter'

describe('RateLimiter', () => {
  beforeEach(() => {
    vi.useFakeTimers()
    vi.setSystemTime(0)
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('allows the first request', () => {
    const limiter = new RateLimiter({ max: 5, windowMs: 1000, mode: 'fixed' })
    expect(limiter.allow('user-1')).toBe(true)
  })

  it('fixed mode: allows up to max in a window then denies', () => {
    const limiter = new RateLimiter({ max: 5, windowMs: 1000, mode: 'fixed' })
    for (let i = 0; i < 5; i++) {
      expect(limiter.allow('user-1')).toBe(true)
    }
    expect(limiter.allow('user-1')).toBe(false)
  })

  it('fixed mode: capacity resets after the window ends', () => {
    const limiter = new RateLimiter({ max: 2, windowMs: 1000, mode: 'fixed' })
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(false)
    vi.setSystemTime(1000)
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(false)
  })

  it('tracks keys independently', () => {
    const limiter = new RateLimiter({ max: 2, windowMs: 1000, mode: 'fixed' })
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(false)
    expect(limiter.allow('user-2')).toBe(true)
    expect(limiter.allow('user-2')).toBe(true)
    expect(limiter.allow('user-2')).toBe(false)
  })

  it('sliding mode: denies the 6th call within the trailing window', () => {
    const limiter = new RateLimiter({ max: 5, windowMs: 1000, mode: 'sliding' })
    for (let i = 0; i < 5; i++) {
      expect(limiter.allow('user-1')).toBe(true)
    }
    vi.setSystemTime(500)
    expect(limiter.allow('user-1')).toBe(false)
  })

  it('sliding mode: denies across fixed-window boundary while calls are still in trailing window', () => {
    const limiter = new RateLimiter({ max: 5, windowMs: 1000, mode: 'sliding' })
    vi.setSystemTime(950)
    for (let i = 0; i < 5; i++) {
      expect(limiter.allow('user-1')).toBe(true)
    }
    vi.setSystemTime(1100)
    expect(limiter.allow('user-1')).toBe(false)
  })

  it('sliding mode: allows after oldest call ages out', () => {
    const limiter = new RateLimiter({ max: 5, windowMs: 1000, mode: 'sliding' })
    for (let i = 0; i < 5; i++) {
      expect(limiter.allow('user-1')).toBe(true)
    }
    vi.setSystemTime(1100)
    expect(limiter.allow('user-1')).toBe(true)
  })

  it('sliding mode: tracks keys independently', () => {
    const limiter = new RateLimiter({ max: 2, windowMs: 1000, mode: 'sliding' })
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(false)
    expect(limiter.allow('user-2')).toBe(true)
    expect(limiter.allow('user-2')).toBe(true)
    expect(limiter.allow('user-2')).toBe(false)
  })
})

